CREATE COLUMN TABLE "TEST_AP"."APZ_OHWC" ("Code" VARCHAR(10) NOT NULL , "Name" NVARCHAR(254) NOT NULL , "Rate" DECIMAL(19,6) CS_FIXED NOT NULL , "WorkType" INTEGER CS_INT NOT NULL , "Remarks" NVARCHAR(254), "Color" INTEGER CS_INT, "Branch" INTEGER CS_INT NOT NULL , "Status" VARCHAR(1) DEFAULT 'A', "LogInstanc" INTEGER CS_INT, "UserSign" INTEGER CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("Code", "Branch")) UNLOAD PRIORITY 5  AUTO MERGE 